ALTER TABLE public.projects ADD COLUMN creator_user_id uuid, ADD COLUMN privacy text NOT NULL DEFAULT 'approval_required', ADD COLUMN general_solution text NOT NULL DEFAULT '', ADD COLUMN available_positions text[] NOT NULL DEFAULT '{}', ADD COLUMN technical_notes text NOT NULL DEFAULT '', ADD COLUMN confidential_notes text NOT NULL DEFAULT '', ADD COLUMN document_links text[] NOT NULL DEFAULT '{}';
UPDATE public.projects p SET creator_user_id=pr.user_id, privacy='public_discovery', general_solution=p.solution FROM public.profiles pr WHERE pr.id=p.owner_id;
ALTER TABLE public.projects ADD CONSTRAINT project_privacy_valid CHECK (privacy IN ('public_discovery','approval_required','private_team'));
CREATE TABLE public.project_join_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE, profile_id uuid NOT NULL REFERENCES public.profiles(id), message text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,profile_id));
GRANT SELECT,INSERT,UPDATE ON public.project_join_requests TO authenticated;
GRANT ALL ON public.project_join_requests TO service_role;
ALTER TABLE public.project_join_requests ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.has_project_access(_project uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.owns_project(_project) OR EXISTS(SELECT 1 FROM public.invitations WHERE project_id=_project AND profile_id=public.my_profile_id() AND status='accepted') OR EXISTS(SELECT 1 FROM public.project_join_requests WHERE project_id=_project AND profile_id=public.my_profile_id() AND status='accepted')); $$;
REVOKE ALL ON FUNCTION public.has_project_access(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_project_access(uuid) TO authenticated,service_role;
CREATE POLICY "requester and owner read requests" ON public.project_join_requests FOR SELECT TO authenticated USING(profile_id=public.my_profile_id() OR public.owns_project(project_id));
CREATE POLICY "students request discoverable projects" ON public.project_join_requests FOR INSERT TO authenticated WITH CHECK(profile_id=public.my_profile_id() AND status='pending' AND NOT public.owns_project(project_id) AND EXISTS(SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.privacy<>'private_team'));
CREATE POLICY "owner reviews requests" ON public.project_join_requests FOR UPDATE TO authenticated USING(public.owns_project(project_id)) WITH CHECK(public.owns_project(project_id));
CREATE OR REPLACE FUNCTION public.guard_project_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN IF NOT NEW.is_sample THEN IF auth.uid() IS NULL OR NEW.owner_id IS DISTINCT FROM public.my_profile_id() THEN RAISE EXCEPTION 'Only your own account may create projects'; END IF; IF NEW.creator_user_id IS NOT NULL AND NEW.creator_user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Invalid creator'; END IF; NEW.creator_user_id:=auth.uid(); END IF; ELSE IF NEW.id IS DISTINCT FROM OLD.id OR NEW.owner_id IS DISTINCT FROM OLD.owner_id OR NEW.creator_user_id IS DISTINCT FROM OLD.creator_user_id OR NEW.is_sample IS DISTINCT FROM OLD.is_sample THEN RAISE EXCEPTION 'Project ownership cannot change'; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER guard_project_identity BEFORE INSERT OR UPDATE ON public.projects FOR EACH ROW EXECUTE FUNCTION public.guard_project_identity();
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
DROP POLICY "projects readable" ON public.projects;
CREATE POLICY "authorized full project reads" ON public.projects FOR SELECT TO authenticated USING(public.has_project_access(id));
ALTER POLICY "owner inserts" ON public.projects WITH CHECK(owner_id=public.my_profile_id() AND creator_user_id=auth.uid() AND NOT is_sample);
ALTER POLICY "owner updates" ON public.projects USING(owner_id=public.my_profile_id() AND creator_user_id=auth.uid()) WITH CHECK(owner_id=public.my_profile_id() AND creator_user_id=auth.uid() AND NOT is_sample);
ALTER POLICY "owner deletes" ON public.projects USING(owner_id=public.my_profile_id() AND creator_user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.project_discovery() RETURNS TABLE(id uuid,owner_id uuid,title text,problem text,solution text,target_users text,required_skills text[],interests text[],expected_hours integer,stage text,checklist jsonb,roadmap_stage integer,is_sample boolean,created_at timestamptz,privacy text,available_positions text[]) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.owner_id,p.title,p.problem,CASE WHEN p.privacy='public_discovery' THEN p.general_solution ELSE '' END,''::text,p.required_skills,p.interests,p.expected_hours,p.stage,'{}'::jsonb,1,p.is_sample,p.created_at,p.privacy,p.available_positions FROM public.projects p WHERE p.privacy<>'private_team' ORDER BY p.created_at DESC; $$;
REVOKE ALL ON FUNCTION public.project_discovery() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.project_discovery() TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.discoverable_project(_project uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.projects WHERE id=_project AND privacy<>'private_team'); $$;
REVOKE ALL ON FUNCTION public.discoverable_project(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.discoverable_project(uuid) TO authenticated,service_role;
ALTER POLICY "students request discoverable projects" ON public.project_join_requests WITH CHECK(profile_id=public.my_profile_id() AND status='pending' AND NOT public.owns_project(project_id) AND public.discoverable_project(project_id) AND NOT public.has_project_access(project_id));
CREATE OR REPLACE FUNCTION public.guard_join_request() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF NEW.id IS DISTINCT FROM OLD.id OR NEW.project_id IS DISTINCT FROM OLD.project_id OR NEW.profile_id IS DISTINCT FROM OLD.profile_id OR NEW.message IS DISTINCT FROM OLD.message OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'Request identity cannot change'; END IF; IF NOT public.owns_project(OLD.project_id) OR OLD.status<>'pending' OR NEW.status NOT IN ('accepted','declined') THEN RAISE EXCEPTION 'Only owners review pending requests'; END IF; ELSE IF length(NEW.message)>2000 THEN RAISE EXCEPTION 'Request message is too long'; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER guard_join_request BEFORE INSERT OR UPDATE ON public.project_join_requests FOR EACH ROW EXECUTE FUNCTION public.guard_join_request();
CREATE OR REPLACE FUNCTION public.can_submit_roadmap(_project uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_project_access(_project); $$;
ALTER POLICY "see own or project invites" ON public.invitations USING(profile_id=public.my_profile_id() OR public.owns_project(project_id) OR (status='accepted' AND public.has_project_access(project_id)));
CREATE OR REPLACE FUNCTION public.guard_invitation_response() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.id IS DISTINCT FROM OLD.id OR NEW.project_id IS DISTINCT FROM OLD.project_id OR NEW.profile_id IS DISTINCT FROM OLD.profile_id OR NEW.message IS DISTINCT FROM OLD.message OR NEW.match_score IS DISTINCT FROM OLD.match_score OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'Invitation identity cannot change'; END IF; IF OLD.status<>'pending' OR NEW.status NOT IN ('accepted','declined') THEN RAISE EXCEPTION 'Only pending invitations may be answered'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER guard_invitation_response BEFORE UPDATE ON public.invitations FOR EACH ROW EXECUTE FUNCTION public.guard_invitation_response();
CREATE OR REPLACE FUNCTION public.project_team(_project uuid) RETURNS TABLE(profile_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT owner_id FROM public.projects WHERE id=_project AND public.has_project_access(_project) UNION SELECT i.profile_id FROM public.invitations i WHERE i.project_id=_project AND i.status='accepted' AND public.has_project_access(_project) UNION SELECT r.profile_id FROM public.project_join_requests r WHERE r.project_id=_project AND r.status='accepted' AND public.has_project_access(_project); $$;
REVOKE ALL ON FUNCTION public.project_team(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.project_team(uuid) TO authenticated,service_role;